{"root_causes":[{"service":"checkout","fault_kind":"http_slow","evidence":[{"kind":"trace","sql":"SELECT 'norm' src, count(*) n FROM normal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge' UNION ALL SELECT 'abn' src, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge'","claim":"Checkout's PaymentService/Charge client spans fall from 18 in the normal period to 0 in the incident window."},{"kind":"trace","sql":"SELECT 'norm' src, count(*) n FROM normal_traces WHERE service_name='payment' UNION ALL SELECT 'abn' src, count(*) n FROM abnormal_traces WHERE service_name='payment'","claim":"Payment emits no server spans during the incident (36 in normal, 0 in abnormal), so checkout's charge requests never reach it."},{"kind":"metric","sql":"SELECT time, value FROM abnormal_metrics_sum WHERE metric='app.payment.transactions' ORDER BY time","claim":"Payment transaction counter stays flat at 65/508 across the whole incident window, so no charges complete."},{"kind":"trace","sql":"SELECT span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') AND attr_status_code='Error' GROUP BY 1","claim":"All 16 frontend POST /api/checkout requests fail after roughly 200 to 300 seconds; checkout's PlaceOrder span never completes."},{"kind":"trace","sql":"SELECT span_name, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name IN ('oteldemo.CartService/GetCart','oteldemo.CurrencyService/Convert','oteldemo.ProductCatalogService/GetProduct','HTTP POST') GROUP BY 1","claim":"Checkout's other outgoing calls (cart, currency, product-catalog, shipping) still complete with normal latency, so the fault is path-specific to the payment call."}],"propagation":[{"from":"checkout","to":"frontend","evidence":[{"kind":"trace","sql":"SELECT span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY 1","claim":"Frontend's checkout server and PlaceOrder client spans fail with ~200 s latency, matching checkout's stalled PlaceOrder."}]},{"from":"frontend","to":"frontend-proxy","evidence":[{"kind":"trace","sql":"SELECT service_name, span_name, count(*) n, max(duration)/1e9 max_s FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' AND attr_status_code='Error' GROUP BY 1,2","claim":"Frontend-proxy ingress requests error out at about 15 s, the timeout for checkout POSTs forwarded through frontend."}]}]}
